    from math import gcd

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    points = defaultdict(list)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                points[grid[r][c]].append((r, c))

    for color, ps in points.items():
        if len(ps) < 2:
            continue

        # Find a direction shared by the marks of this color.
        a, b = max(
            ((ps[i], ps[j]) for i in range(len(ps)) for j in range(i + 1, len(ps))),
            key=lambda pair: abs(pair[0][0] - pair[1][0]) +
                             abs(pair[0][1] - pair[1][1])
        )
        dr, dc = b[0] - a[0], b[1] - a[1]
        g = gcd(abs(dr), abs(dc))
        dr, dc = dr // g, dc // g

        # Extend both ends of that line, stopping at any existing mark.
        values = [r * dr + c * dc for r, c in ps]
        for r, c in ps:
            v = r * dr + c * dc
            for sr, sc in ((-dr, -dc), (dr, dc)):
                if (sr, sc) == (-dr, -dc) and v != min(values):
                    continue
                if (sr, sc) == (dr, dc) and v != max(values):
                    continue
                rr, cc = r + sr, c + sc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += sr
                    cc += sc
    return out
